<script setup lang="ts">import {fixed,probability,logValue} from '../utils/format';defineProps<{candidate:any}>();function branchWeights(inference:any){const weights=inference.weights||{};return Object.entries(weights).map(([k,v]:[string,any])=>k+'=['+v.join(',')+']').join(' · ')||'无'}function weightedPart(candidate:any,b:any){if(!b.inference)return'−∞';return b.inference.log_normalizer!==undefined?logValue(b.inference.log_normalizer):logValue(candidate.marginal.log_evidence)}</script><template><section class="branch-panel"><p class="eyebrow">EXPECTED ENTROPY / RAW BRANCH RECORD</p><h2>{{candidate.node_id}} · 候选分支明细</h2><div class="table-wrap"><table><thead><tr><th>状态</th><th>P(X|E)</th><th>log P(X|E)</th><th>H(Q|E,X) bit</th><th>P(Q=1|E,X)</th><th>分支软权重</th><th>加权logZ</th><th>证据概率log P(E,X)</th></tr></thead><tbody><tr v-for="b in candidate.branches" :key="b.state"><td>{{b.state}}</td><td>{{probability(b.probability,b.probability_underflow)}}</td><td>{{logValue(b.log_probability)}}</td><td>{{b.conditional_entropy===null?'严格零分支跳过':fixed(b.conditional_entropy,6)}}</td><td>{{b.inference?probability(b.inference.posterior[1].probability,b.inference.posterior[1].probability_underflow):'—'}}</td><td>{{b.inference?branchWeights(b.inference):'—'}}</td><td>{{weightedPart(candidate,b)}}</td><td>{{b.inference&&b.inference.log_evidence_probability!==undefined?logValue(b.inference.log_evidence_probability):(b.inference?'—':'−∞')}}</td></tr></tbody></table></div><p class="method-note">H当前={{fixed(candidate.prior_entropy,8)}}；期望={{fixed(candidate.expected_entropy,8)}}；原始IG={{fixed(candidate.raw_information_gain,10)}} bit。微负容差{{candidate.negative_tolerance}}，截断标记{{candidate.micro_negative_clipped}}。基准加权logZ={{logValue(candidate.marginal.log_normalizer??candidate.marginal.log_evidence)}}；证据概率log P(E)={{candidate.marginal.log_evidence_probability!==undefined?logValue(candidate.marginal.log_evidence_probability):'同logZ（旧底稿）'}}。</p></section></template>
